import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import '../api/api_client.dart'  import '../widgets/loading_widget.dart'  import '../widgets/empty_state.dart'    class BankScreen extends ConsumerStatefulWidget {    const BankScreen({super.key})      @override    ConsumerState<BankScreen> createState() => _BankScreenState()  }    class _BankScreenState extends ConsumerState<BankScreen> {    List<dynamic> _connections = []    bool _isLoading = true    bool _isSyncing = false      @override    void initState() {      super.initState()      _loadConnections()    }      Future<void> _loadConnections() async {      try {        final connections = await ApiClient().getBankConnections()        if (mounted) setState(() { _connections = connections; _isLoading = false })      } catch (e) {        if (mounted) setState(() => _isLoading = false)      }    }      Future<void> _syncBank(int connectionId) async {      setState(() => _isSyncing = true)      try {        final result = await ApiClient().syncBank(connectionId)        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Синхронизировано: ${result['imported'] ?? 0} операций')),          )        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Ошибка синхронизации: $e')),          )        }      } finally {        if (mounted) setState(() => _isSyncing = false)      }    }      final Map<String, Map<String, dynamic>> _bankInfo = {    'tinkoff': {'name': 'Тинькофф', 'color': Colors.yellow[700], 'icon': Icons.account_balance},    'sber': {'name': 'СберБанк', 'color': Colors.green[700], 'icon': Icons.account_balance},    'vtb': {'name': 'ВТБ', 'color': Colors.blue[700], 'icon': Icons.account_balance},    'raiff': {'name': 'Райффайзен', 'color': Colors.orange[700], 'icon': Icons.account_balance},    'alfa': {'name': 'Альфа-Банк', 'color': Colors.red[700], 'icon': Icons.account_balance},  }      @override    Widget build(BuildContext context) {      return Scaffold(        appBar: AppBar(          title: const Text('Банк'),          actions: [            IconButton(              icon: const Icon(Icons.add),              onPressed: () {},            ),          ],        ),        body: _isLoading            ? const LoadingWidget()            : _connections.isEmpty                ? EmptyState(                    icon: Icons.account_balance_outlined,                    title: 'Нет подключенных банков',                    subtitle: 'Подключите Тинькофф, Сбер или другой банк для автоматической синхронизации операций',                  )                : RefreshIndicator(                    onRefresh: _loadConnections,                    child: ListView.builder(                      padding: const EdgeInsets.all(16),                      itemCount: _connections.length,                      itemBuilder: (context, index) {                        final conn = _connections[index]                        final info = _bankInfo[conn['bank_name']] ?? {'name': conn['bank_name'], 'color': Colors.grey, 'icon': Icons.account_balance}                        final isSuccess = conn['last_sync_status'] == 'success'                          return Card(                          margin: const EdgeInsets.only(bottom: 12),                          child: Padding(                            padding: const EdgeInsets.all(16),                            child: Column(                              crossAxisAlignment: CrossAxisAlignment.start,                              children: [                                Row(                                  children: [                                    Container(                                      padding: const EdgeInsets.all(10),                                      decoration: BoxDecoration(                                        color: (info['color'] as Color?)?.withOpacity(0.1),                                        borderRadius: BorderRadius.circular(10),                                      ),                                      child: Icon(                                        info['icon'] as IconData?,                                        color: info['color'] as Color?,                                        size: 24,                                      ),                                    ),                                    const SizedBox(width: 12),                                    Expanded(                                      child: Column(                                        crossAxisAlignment: CrossAxisAlignment.start,                                        children: [                                          Text(                                            info['name'] as String? ?? conn['bank_name'],                                            style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w600),                                          ),                                          Text(                                            conn['account_name'] ?? conn['account_number'] ?? 'Счет',                                            style: TextStyle(fontSize: 12, color: Colors.grey[600]),                                          ),                                        ],                                      ),                                    ),                                    Container(                                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),                                      decoration: BoxDecoration(                                        color: conn['is_active'] == true                                            ? Colors.green.withOpacity(0.1)                                            : Colors.red.withOpacity(0.1),                                        borderRadius: BorderRadius.circular(8),                                      ),                                      child: Text(                                        conn['is_active'] == true ? 'Активен' : 'Неактивен',                                        style: TextStyle(                                          fontSize: 10,                                          color: conn['is_active'] == true ? Colors.green[700] : Colors.red[700],                                        ),                                      ),                                    ),                                  ],                                ),                                const SizedBox(height: 16),                                Row(                                  children: [                                    Expanded(                                      child: _BankStat(                                        label: 'Синхронизировано',                                        value: '${conn['total_synced'] ?? 0}',                                      ),                                    ),                                    Expanded(                                      child: _BankStat(                                        label: 'Последняя синхронизация',                                        value: conn['last_sync_at'] != null                                            ? '${DateTime.parse(conn['last_sync_at']).day.toString().padLeft(2, '0')}.${DateTime.parse(conn['last_sync_at']).month.toString().padLeft(2, '0')}'                                            : 'Никогда',                                      ),                                    ),                                    Expanded(                                      child: _BankStat(                                        label: 'Статус',                                        value: conn['last_sync_status'] == 'success'                                            ? 'OK'                                            : conn['last_sync_status'] == 'error'                                                ? 'Ошибка'                                                : 'Ожидание',                                        valueColor: isSuccess ? Colors.green : Colors.orange,                                      ),                                    ),                                  ],                                ),                                const SizedBox(height: 12),                                SizedBox(                                  width: double.infinity,                                  child: ElevatedButton.icon(                                    onPressed: _isSyncing ? null : () => _syncBank(conn['id']),                                    icon: _isSyncing                                        ? const SizedBox(                                            height: 16,                                            width: 16,                                            child: CircularProgressIndicator(strokeWidth: 2),                                          )                                        : const Icon(Icons.sync, size: 18),                                    label: Text(_isSyncing ? 'Синхронизация...' : 'Синхронизировать'),                                    style: ElevatedButton.styleFrom(                                      padding: const EdgeInsets.symmetric(vertical: 12),                                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(10)),                                    ),                                  ),                                ),                              ],                            ),                          ),                        )                      },                    ),                  ),      )    }  }    class _BankStat extends StatelessWidget {    final String label    final String value    final Color? valueColor      const _BankStat({required this.label, required this.value, this.valueColor})      @override    Widget build(BuildContext context) {      return Column(        children: [          Text(            value,            style: TextStyle(              fontSize: 16,              fontWeight: FontWeight.bold,              color: valueColor,            ),          ),          const SizedBox(height: 2),          Text(            label,            style: TextStyle(fontSize: 10, color: Colors.grey[500]),            textAlign: TextAlign.center,          ),        ],      )    }  }